def calibrate_btagPNetQvG(pt_vals, eta_vals, tag_vals):
    """
    Calibrate jet btagPNetQvG. Jets outside calibration range are left unchanged.
    """
    pt_vals  = np.asarray(pt_vals,  dtype=float)
    abs_eta  = np.abs(np.asarray(eta_vals, dtype=float))
    tag_vals = np.asarray(tag_vals, dtype=float)
    cal_vals = tag_vals.copy()

    in_cen = (abs_eta <= 2.5) & (pt_vals >= 30.0) & (pt_vals <= 450.0)
    if in_cen.any():
        pt_idx  = np.clip(np.digitize(pt_vals[in_cen], pt_edges_central)  - 1,
                          0, len(pt_edges_central)  - 2)
        eta_idx = np.clip(np.digitize(abs_eta[in_cen], eta_edges_central) - 1,
                          0, len(eta_edges_central) - 2)
        tv = tag_vals[in_cen]; cal_in = tv.copy()
        for i in np.unique(pt_idx):
            for j in np.unique(eta_idx[pt_idx == i]):
                mask = (pt_idx == i) & (eta_idx == j)
                if not mask.any(): continue
                quantiles    = np.interp(tv[mask], tag_edges, cdf_mc_cen[i, j])
                _, uidx      = np.unique(cdf_data_cen[i, j], return_index=True)
                cal_in[mask] = np.interp(quantiles, cdf_data_cen[i, j][uidx],
                                         tag_edges[uidx])
        cal_vals[in_cen] = cal_in

    in_fwd = (abs_eta > 2.5) & (abs_eta <= 4.7) & (pt_vals >= 50.0) & (pt_vals <= 450.0)
    if in_fwd.any():
        pt_idx  = np.clip(np.digitize(pt_vals[in_fwd], pt_edges_forward)  - 1,
                          0, len(pt_edges_forward)  - 2)
        eta_idx = np.clip(np.digitize(abs_eta[in_fwd], eta_edges_forward) - 1,
                          0, len(eta_edges_forward) - 2)
        tv = tag_vals[in_fwd]; cal_in = tv.copy()
        for i in np.unique(pt_idx):
            for j in np.unique(eta_idx[pt_idx == i]):
                mask = (pt_idx == i) & (eta_idx == j)
                if not mask.any(): continue
                quantiles    = np.interp(tv[mask], tag_edges, cdf_mc_fwd[i, j])
                _, uidx      = np.unique(cdf_data_fwd[i, j], return_index=True)
                cal_in[mask] = np.interp(quantiles, cdf_data_fwd[i, j][uidx],
                                         tag_edges[uidx])
        cal_vals[in_fwd] = cal_in

    return cal_vals
